def append_task_section(self, plan_id: str, task_id: str, section_name: str, content: str) -> None:
    """Append and persist a task section."""
    self._mutate(
        lambda: (
            plan_id,
            super(ContentTaskProvider, self).append_task_section(plan_id, task_id, section_name, content),
        )
    )

def _flush(self, plan_id: str, owner_reference: str | None = None) -> None:
    record = self._provider.put_content(
        ContentWrite(
            reference=ContentRef(kind=ContentKind.PLAN, name=plan_id),
            content=json.dumps(self._plans[plan_id], separators=(",", ":"), default=str),
            owner_reference=owner_reference,
            expected_revision=self._revisions.get(plan_id, ""),
        )
    )
    self._revisions[plan_id] = record.revision

def _mutate(
    self, mutation: Callable[[], tuple[str | None, _MutationResult]], *, owner_reference: str | None = None
) -> _MutationResult:
    plans_before = copy.deepcopy(self._plans)
    revisions_before = self._revisions.copy()
    plan_id, result = mutation()
    if plan_id is None:
        return result
    try:
        self._flush(plan_id, owner_reference)
    except ContentProviderError:
        try:
            self._refresh(plan_id)
        except ContentNotFoundError:
            self._plans.pop(plan_id, None)
            self._revisions.pop(plan_id, None)
        except ContentProviderError:
            self._plans = plans_before
            self._revisions = revisions_before
        raise
    return result

def _refresh(self, plan_id: str) -> None:
    record = self._provider.get_content(ContentRef(kind=ContentKind.PLAN, name=plan_id))
    self._plans[plan_id] = parse_plan_content(record.content, record.reference.name)
    self._revisions[plan_id] = record.revision

def _mutate(
    self, mutation: Callable[[], tuple[str | None, _MutationResult]], *, owner_reference: str | None = None
) -> _MutationResult:
    plans_before = copy.deepcopy(self._plans)
    revisions_before = self._revisions.copy()
    plan_id, result = mutation()
    if plan_id is None:
        return result
    try:
        self._flush(plan_id, owner_reference)
    except ContentProviderError:
        try:
            self._refresh(plan_id)
        except ContentNotFoundError:
            self._plans.pop(plan_id, None)
            self._revisions.pop(plan_id, None)
        except ContentProviderError:
            self._plans = plans_before
            self._revisions = revisions_before
        raise

@staticmethod
def _record_for_write(request: ContentWrite, current: ContentRecord | None) -> ContentRecord:
    owner_reference = (
        request.owner_reference
        if request.owner_reference is not None
        else (current.owner_reference if current is not None else request.reference.namespace)
    )
    if request.create_only and current is not None:
        raise ContentConflictError("Content already exists")
    if request.expected_revision and (current is None or current.revision != request.expected_revision):
        raise ContentConflictError("Content revision no longer matches")
    if current is not None and current.content == request.content and current.owner_reference == owner_reference:
        return current
    return ContentRecord(reference=request.reference, owner_reference=owner_reference, content=request.content)

def put_content(self, request: ContentWrite) -> ContentRecord:
    """Create or replace one in-memory content record."""
    with self._content_lock:
        key = self._content_key(request.reference)
        current = self._content.get(key)
        current_revision = current.revision if current is not None else ""
        if request.create_only and current is not None:
            raise ContentConflictError("Content already exists")
        if request.expected_revision and request.expected_revision != current_revision:
            raise ContentConflictError("Content revision no longer matches")

def put_content(self, request: ContentWrite) -> ContentRecord:
    """Create or replace one record in the native Beads KV store."""
    with _beads_content_lock(self._runner):
        current = self._find_content(request.reference)
        current_revision = current.revision if current is not None else ""
        if request.create_only and current is not None:
            raise ContentConflictError("Content already exists")
        if request.expected_revision and request.expected_revision != current_revision:
            raise ContentConflictError("Content revision no longer matches")
        owner_reference = request.reference.namespace
        if request.reference.kind in {ContentKind.PLAN, ContentKind.DISPATCH_PLAN}:
            owner_reference = (
                request.owner_reference
                if request.owner_reference is not None
                else current.owner_reference
                if current is not None
                else ""
            )
        record = ContentRecord(
            reference=request.reference,
            owner_reference=owner_reference,
            content=request.content,
            revision=uuid.uuid4().hex,
        )
        try:
            self._runner.run_text([
                "kv",
                "set",
                self._content_key(request.reference),
                json.dumps(record.model_dump(mode="json"), separators=(",", ":")),
            ])
        except (BdNotInstalledError, BdInvocationError, BdJsonDecodeError) as exc:
            raise ContentUnavailableError(f"Beads content store is unavailable: {exc}") from exc
        return record

def _find_content(self, reference: ContentRef) -> ContentRecord | None:
    try:
        raw = self._runner.run_json(["kv", "get", self._content_key(reference)])
    except BdInvocationError as exc:
        if exc.returncode != 1:
            raise ContentUnavailableError(f"Beads content store is unavailable: {exc}") from exc
        try:
            raw = json.loads(exc.stdout)
        except json.JSONDecodeError as decode_error:
            raise ContentUnavailableError(f"Beads content store is unavailable: {decode_error}") from decode_error
    except (BdNotInstalledError, BdJsonDecodeError) as exc:
        raise ContentUnavailableError(f"Beads content store is unavailable: {exc}") from exc
    if not isinstance(raw, dict):
        raise ContentUnavailableError("Beads content store returned an invalid record")
    if raw.get("found") is False:
        return None
    value = raw.get("value")
    if not isinstance(value, str):
        raise ContentUnavailableError("Beads content store returned an invalid record")
    try:
        return ContentRecord.model_validate_json(value)
    except ValidationError as exc:
        raise ContentUnavailableError("Beads content store returned an invalid record") from exc

@staticmethod
def _content_key(reference: ContentRef) -> str:
    digest = hashlib.sha256(reference.model_dump_json().encode()).hexdigest()
    return f"{_CONTENT_KEY_PREFIX}{digest}"

def list_content(self, query: ContentQuery) -> list[ContentRecord]:
    """Return a bounded cache-backed discovery page for GitHub content.

    Returns:
        The requested page of content records.
    """
    return self._content_cache.list_content(query)

def get_content(self, reference: ContentRef) -> ContentRecord:
    """Read authoritative GitHub content or an explicitly stale cached copy.

    Returns:
        The provider or cached logical content record.
    """
    return self._content_cache.get_content(reference)

def put_content(self, request: ContentWrite) -> ContentRecord:
    """Write GitHub content, durably queueing it while GitHub is offline.

    Returns:
        The applied or pending logical content record.
    """
    return self._content_cache.put_content(request)

def _replay_pending_content(self) -> None:
    """Replay durably queued content writes against GitHub."""
    self._content_cache.replay_pending()

def _list_online_content(self, query: ContentQuery) -> list[ContentRecord]:
    """Enumerate authoritative content merged with the legacy stores.

    Returns:
        Every discoverable record, excluding provider-private work-item heads.
    """
    return self._content_migration.list_online(query)

def _read_online_content(self, reference: ContentRef, cached: ContentRecord | None) -> ContentRecord:
    """Read authoritative content, falling back to the legacy stores.

    Returns:
        The resolved content record.
    """
    return self._content_migration.read(reference)

def _write_online_content(self, request: ContentWrite, cached: ContentRecord | None) -> ContentRecord:
    """Write content, migrating a legacy record into the Contents API when needed.

    Returns:
        The written content record.
    """
    return self._content_migration.write(request)

def write(self, request: ContentWrite) -> ContentRecord:
    """Write content, migrating a legacy record into the Contents API when needed.

    An unconditional write goes straight to the Contents API. A conditional
    write whose reference is absent there validates the caller's expectation
    against the legacy record first, then republishes it as a create so the
    Contents API becomes authoritative without dropping the compare-and-swap.

    Returns:
        The written content record.

    Raises:
        ContentConflictError: If the caller's create-only or revision
            expectation no longer holds against the legacy record.
    """
    if not request.expected_revision and not request.create_only:
        return self._contents().put(request)
    try:
        self._contents().get(request.reference)
    except ContentNotFoundError as exc:
        try:
            legacy = self.read_legacy(request.reference)
        except ContentNotFoundError:
            return self._contents().put(request)
        if request.create_only:
            raise ContentConflictError("Content already exists") from exc
        if legacy.revision != request.expected_revision:
            raise ContentConflictError("Content revision no longer matches") from exc
        return self._contents().put(
            request.model_copy(
                update={
                    "owner_reference": (
                        request.owner_reference if request.owner_reference is not None else legacy.owner_reference
                    ),
                    "expected_revision": "",
                    "create_only": True,
                }
            )
        )
    return self._contents().put(request)

def put(self, request: ContentWrite) -> ContentRecord:
    repository = self._repository()
    branch = self._content_branch(repository)
    path = self._path(request.reference)
    for _ in range(_WRITE_ATTEMPTS):
        current = self._existing(repository, path, branch)
        record = self._record_for_write(request, current)
        if current == record:
            return current
        envelope = self._serialize(record)
        if len(envelope.encode()) > _MAX_CONTENT_BYTES:
            raise ContentUnavailableError("GitHub content exceeds the 1 MB Contents API limit")
        try:
            if current is None:
                response = repository.create_file(path, f"Store {request.reference.kind}", envelope, branch=branch)
            else:
                response = repository.update_file(
                    path, f"Store {request.reference.kind}", envelope, current.revision, branch=branch
                )
        except GithubException as exc:
            if exc.status not in _CONFLICT_STATUSES:
                raise ContentUnavailableError(f"GitHub content write failed: {exc}") from exc
            observed = self._existing(repository, path, branch)
            if current is None:
                if observed is not None:
                    raise ContentConflictError("Content already exists") from exc
            elif observed is None or observed.revision != current.revision:
                raise ContentConflictError("Content revision no longer matches") from exc
        else:
            written = response.get("content")
            if not isinstance(written, _ContentsFile):
                raise ContentUnavailableError("GitHub content write response was invalid")
            return self._parse(path, envelope.encode(), written.sha)
    raise ContentUnavailableError("GitHub content write could not advance the selected branch")

def put_content(self, request: ContentWrite) -> ContentRecord:
    return self.put(request)

def _existing(self, repository: _ContentsRepository, path: str, branch: str) -> ContentRecord | None:
    try:
        return self._get(repository, path, branch)
    except ContentNotFoundError:
        return None

@staticmethod
def _record_for_write(request: ContentWrite, current: ContentRecord | None) -> ContentRecord:
    owner_reference = (
        request.owner_reference
        if request.owner_reference is not None
        else (current.owner_reference if current is not None else request.reference.namespace)
    )
    if request.create_only and current is not None:
        raise ContentConflictError("Content already exists")
    if request.expected_revision and (current is None or current.revision != request.expected_revision):
        raise ContentConflictError("Content revision no longer matches")
    if current is not None and current.content == request.content and current.owner_reference == owner_reference:
        return current
    return ContentRecord(reference=request.reference, owner_reference=owner_reference, content=request.content)

def replay_pending(self) -> None:
    """Replay durably queued writes, acknowledging only the ones that land."""
    acknowledgements: list[ReplayAcknowledgement] = []
    for mutation in self._cache.pending_mutations():
        cached = self.cached_content(mutation.write.reference)
        try:
            record = self._provider._write_online_content(mutation.write, cached)
        except (ContentConflictError, UnsupportedCapabilityError) as exc:
            _log.warning("replay rejected %s: %s", mutation.write.reference.model_dump_json(), exc)
            self._cache.reject_pending(mutation.write.reference, mutation.idempotency_key, str(exc))
            continue
        except (BacklogError, ContentUnavailableError, OSError):
            break
        acknowledgements.append(
            ReplayAcknowledgement(
                idempotency_key=mutation.idempotency_key,
                record=record,
                fingerprint=_content_revision(record.content),
            )
        )
    if acknowledgements:
        self._cache.acknowledge_replay(acknowledgements)

def _sam_plan_status(plan: str, plan_dir: str) -> PlanStatus | LedgerPlanStatus:
    """Return plan-level progress summary including autonomy mode.

    Thin adapter: once the ledger holds the plan, reads its progress the way the CLI's
    ledger-backed ``plan status`` command does. Otherwise resolves the content backend via
    ``get_backend`` and delegates to ``dh_core.operations.get_plan_status``. The content-store
    result carries ``state`` so callers can detect drafting plans.
    """

    def _from_content() -> PlanStatus:
        backend = server_backend.get_backend(plan_dir)
        resolved, _ = resolve_provider_plan_address(plan, backend)
        return operations.get_plan_status(backend, resolved)

    return route(plan, on_ledger_call=lambda canonical, conn: ledger.status(conn, canonical), on_content=_from_content)

def claim_task(self, plan_id: str, task_id: str) -> bool:
    """Claim and persist a task.

    Returns:
        Whether the task was claimed.
    """
    try:
        return self._mutate(
            lambda: (
                plan_id if (claimed := super(ContentTaskProvider, self).claim_task(plan_id, task_id)) else None,
                claimed,
            )
        )
    except ContentConflictError:
        return False

@app.command("claim")
def claim(
    address: Annotated[str, typer.Option("--address")],
    plan_dir: Annotated[Path | None, typer.Option("--plan-dir")] = None,
) -> None:
    """Claim a task by transitioning it to in-progress."""
    backend = _backend()
    plan_ref, task_ref = _address(address, backend)
    if task_ref is None:
        _error(f"Address '{address}' does not include a task component")
    task_id = f"T{task_ref}" if task_ref.isdigit() else task_ref
    try:
        _emit(operations.claim_task(backend, plan_ref, task_id))
    except (PlanNotFoundError, TaskNotFoundError, FileNotFoundError, FormatDetectionError, ValueError) as exc:
        _error(str(exc), 2 if isinstance(exc, FormatDetectionError) else 1)

@app.command(name="set")
def active_task_set(
    address: Annotated[str, typer.Option("--address", help="Task address: P{plan}/T{task}")],
    plan_dir: Annotated[Path | None, typer.Option("--plan-dir", help="Plan directory")] = None,
    parent_issue_number: Annotated[
        str | None, typer.Option("--parent-issue", help="Parent issue number or beads nanoid")
    ] = None,
    session_id: Annotated[str | None, _SESSION_OPTION] = None,
) -> None:
    """Park a task address as the active task for a session."""
    try:
        plan_ref, task_id = parse_address(address)
    except AddressingError as exc:
        err(str(exc))
    raw_plan, _, _ = address.partition("/")
    if re.fullmatch(r"P[0-9a-f]{8}", raw_plan, re.IGNORECASE):
        plan_ref = raw_plan
    if not task_id:
        err(f"Address '{address}' must include a task ID (e.g. --address P<plan>/T<task>).")
    task_id = f"T{task_id}" if task_id.isdigit() else task_id
    # Typer hands every option through as str, but ActiveTaskContext accepts
    # int (GitHub issue number) or a beads-ID str. Coerce digit-only input to
    # int so `--parent-issue 42` behaves the same as the MCP tool, which is
    # typed `str | int`.
    resolved_parent: str | int | None = parent_issue_number
    if parent_issue_number is not None and parent_issue_number.isdigit():
        resolved_parent = int(parent_issue_number)
    try:
        resolved_session = operations.require_session_id(session_id)
    except operations.MissingSessionIdError as exc:
        err(str(exc))
    result = operations.set_active_task(
        _context_backend(),
        resolved_session,
        plan_ref,
        task_id,
        str(plan_dir) if plan_dir is not None else "plan",
        resolved_parent,
    )
    output_json(result)

def _load_yaml_config(path: Path) -> dict[str, object] | None:
    """Read a YAML config file and return parsed content, or None on any error.

    Args:
        path: Path to the YAML config file.

    Returns:
        Parsed dict if successful, None if file absent or any error occurs.
    """
    if not path.is_file():
        return None
    try:
        data = _YAML.load(path.read_text(encoding="utf-8"))
    except _YAML_PARSE_ERRORS:
        return None
    else:
        return data if _is_str_dict(data) else None

